<template><div class="product-shell">
<header class="product-header"><BrandMark/><div class="site-title">{{siteName}}</div><div class="header-tools"><span class="badge" :class="online===2?'success':'neutral'"><i/>设备 {{online}}/2</span><RouterLink v-if="auth.can('events')" to="/events" class="icon-button" aria-label="打开事件中心" title="打开事件中心"><Bell :size="19"/></RouterLink><button class="icon-button" aria-label="使用帮助" @click="helpOpen=true"><CircleHelp :size="19"/></button><div class="account-wrap"><button class="account-button" @click="accountOpen=!accountOpen" :aria-expanded="accountOpen"><span class="avatar"><UserRound :size="18"/></span><span>{{auth.user?.displayName}}</span><ChevronDown :size="14"/></button><div v-if="accountOpen" class="account-menu"><small class="muted">{{auth.user?.username}}</small><button @click="logout" :disabled="logoutBusy"><LogOut :size="15"/>{{logoutBusy?'正在退出…':'退出登录'}}</button></div></div></div></header>
<aside class="product-sidebar"><div class="nav-caption">工作空间</div><nav><RouterLink v-for="item in navigation" :key="item.path" :to="item.path" class="nav-item" :class="{active:active(item.path)}"><component :is="item.icon" :size="19"/><span>{{item.name}}</span></RouterLink></nav><div class="sidebar-bottom"><span class="status-dot" :class="{online:camera.status.serviceState==='ready'}"></span>{{camera.status.serviceState==='ready'?'服务已连接':'服务未连接'}}<small>云瞳 AIRSPACE · 2.0</small></div></aside>
<main class="product-main"><RouterView v-slot="{Component}"><Transition name="page" mode="out-in"><component :is="Component" :key="route.path"/></Transition></RouterView></main><ToastStack :toasts="camera.toasts"/>
<dialog :open="helpOpen" class="help-dialog" @keydown.esc="helpOpen=false"><div class="page-heading"><h2>使用帮助</h2><button class="icon-button" @click="helpOpen=false" aria-label="关闭帮助"><X :size="18"/></button></div><p>接入两路摄像机，在空间标定中导入已验证的参数，然后进入实时监控启动检测。</p><p>新目标进入事件中心，复核结论和操作记录保存在本机数据库中。录像回放可检索已经保存的文件。</p><p v-if="!auth.can('devices')" class="muted">设备接入与标定由本单位设备管理员操作。</p><RouterLink v-if="auth.can('devices')" class="btn primary" to="/devices" @click="helpOpen=false">设备与标定<ArrowRight :size="16"/></RouterLink></dialog></div></template>
<script setup lang="ts">
import{computed,onMounted,onUnmounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import{Monitor,CircleAlert,SquarePlay,Layers,Settings,Bell,CircleHelp,UserRound,ChevronDown,LogOut,X,ArrowRight}from'lucide-vue-next';
import BrandMark from '@/components/BrandMark.vue';import ToastStack from '@/components/ToastStack.vue';import{useAuthStore}from'@/stores/auth';import{useCameraStore}from'@/stores/camera';
const auth=useAuthStore(),camera=useCameraStore(),route=useRoute(),router=useRouter();const accountOpen=ref(false),helpOpen=ref(false),logoutBusy=ref(false);
const siteName=computed(()=>auth.siteName);
const online=computed(()=>Object.values(camera.status.cameras).filter(c=>c.state==='streaming').length);
const navigation=computed(()=>[{path:'/home',name:'运行总览',icon:Monitor,permission:'monitor'},{path:'/workbench',name:'实时监控',icon:CircleAlert,permission:'monitor'},{path:'/events',name:'事件中心',icon:CircleAlert,permission:'events'},{path:'/playback',name:'录像回放',icon:SquarePlay,permission:'playback'},{path:'/devices',name:'设备与标定',icon:Layers,permission:'devices'},{path:auth.can('settings')?'/settings':'/settings?tab=audit',name:auth.can('settings')?'系统设置':'操作日志',icon:Settings,permission:auth.can('settings')?'settings':'audit'}].filter(i=>auth.can(i.permission)));
const active=(path:string)=>path==='/devices'?['/devices','/calibration'].includes(route.path):path.startsWith('/settings')?['/settings','/models'].includes(route.path):route.path===path;
let stopped=false;let timeout:ReturnType<typeof setTimeout>|undefined;async function poll(){if(stopped)return;await camera.refreshStatus();if(!stopped)timeout=setTimeout(poll,camera.status.detecting?400:2000)}
async function logout(){if(logoutBusy.value)return;logoutBusy.value=true;try{await auth.logout();await router.replace('/login')}catch(e){camera.toast((e as Error).message,'error')}finally{logoutBusy.value=false}}
onMounted(()=>{void poll();});onUnmounted(()=>{stopped=true;clearTimeout(timeout)});
</script>
